use vstd::prelude::*;

verus! {

fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        // all entries are either 1.0 (interior) or 0.5 (endpoints)
        forall|i: int|
            0 <= i < result.len() ==>
                (result[i] == 1.0f32 || result[i] == 0.5f32),
        // endpoints are 0.5
        result[0] == 0.5f32,
        result[(result.len() - 1) as int] == 0.5f32,
        // interior (if any) is 1.0
        forall|i: int|
            0 < i && i < result.len() - 1 ==> result[i] == 1.0f32,
{
    let n = x.len();
    assert!(n > 0, "input must be non-empty");

    let mut result = vec![1.0f32; n];

    // Endpoints always get weight 0.5 (for n == 1, this sets the only element to 0.5).
    result[0] = 0.5;
    result[n - 1] = 0.5;

    // Help the verifier connect `n` and `result.len()`.
    assert(result.len() == n);

    result
}

} // verus!

